#include <assert.h>
#include <stdlib.h>
#include "dk1/level_terrain_config.h"
#include "dk1/player_live_runtime.h"
int main(void){const char*path=getenv("DK1_TEST_ROM");Dk1OwnedRom owned={0};Dk1RomImage rom;Dk1LevelTerrainConfig cfg;Dk1PlayerTerrainRuntime terrain;Dk1PlayerPreviewRuntime p;Dk1PlayerLiveRuntime live;uint16_t cy=0;unsigned i;if(!path)path="/mnt/data/Donkey Kong Country (USA) (Rev 2).sfc";assert(dk1_rom_load_file(path,&owned,&rom));assert(dk1_level_terrain_config_read(&rom,0,&cfg));assert(dk1_player_terrain_init(&terrain,&rom,cfg,5120u));dk1_player_preview_init(&p,48u,192);assert(dk1_player_terrain_place(&terrain,&p,64u,&cy));dk1_player_live_init(&live);assert(live.state==1u&&live.handler_pc==0xBF87FDu);dk1_player_live_step(&live,&p,&terrain,DK1_PLAYER_PREVIEW_JUMP,DK1_PLAYER_PREVIEW_JUMP);assert(live.state==11u);assert(live.handler_pc==0xBF8FA7u);assert(live.required_calls==DK1_PLAYER_CALL_MOVE);assert(live.local_steps==1u);for(i=0;i<200u&&p.airborne;i++)dk1_player_live_step(&live,&p,&terrain,0u,0u);assert(!p.airborne);assert(live.state==1u&&live.handler_pc==0xBF87FDu);dk1_player_live_step(&live,&p,&terrain,0u,0u);assert(live.dispatches>1u&&live.plan_steps>0u);dk1_rom_free(&owned);return 0;}
